    public static DocxImportResult Import(string path)
    {
        byte[] source=File.ReadAllBytes(path);byte[] sourceDigest=SHA256.HashData(source);var entries=ReadEntries(source);string document=Utf8(entries,"word/document.xml");string rels=Utf8(entries,"word/_rels/document.xml.rels");
