        int ordinal=0;Guid Add(string type,string role,Dictionary<string,object?> data){Guid id=Ids.NewV4();state.Objects[id]=new(id,type,flow,OrderKey.Initial(ordinal++),role,data);return id;}
        Guid supported=Add("text_block","body",new(StringComparer.Ordinal){{"text",ExtractSupportedTarget(document)},{"interop_feature","supported_edit_target"},{"source_entry","word/document.xml"}});
        Guid requiredUnknown=Add("interop_unknown","provider_required",new(StringComparer.Ordinal){{"text","unknown required provider meaning"},{"interop_feature","unknown_mc"},{"fallback","Static compatible fallback"},{"source_entry","word/document.xml"}});
