        Guid facetId=Ids.NewV4();state.ProviderFacets[facetId]=new(facetId,"docx","unknown_mc",requiredUnknown,ExtensionCoverageKind.Object,ExtensionEditPolicy.MustUnderstandBeforeEdit,unknownPayload,SHA256.HashData(unknownPayload),"exact_source",true);
